fun scopeParams allUserParams usedParams =>
  match List.find? (fun u => !usedParams.contains u && !List.elem u scopeParams) allUserParams with
  | some u => throw (toString "unused universe parameter '" ++ toString u ++ toString "'")
  | none =>
    have result :=
      List.foldl
        (fun result levelName =>
          if Array.elem levelName usedParams = true then levelName :: result else result)
        [] allUserParams;
    have remaining :=
      Array.filter (fun levelParam => !List.elem levelParam allUserParams) usedParams;
    have remaining := remaining.qsort Lean.Name.lt;
    pure (result ++ remaining.toList)

