  (bit : (b : Bool) → (n : ℕ) → n ≠ 0 → motive n → motive (Nat.bit b n)) :
  Nat.binaryRecFromOne zero one bit 1 = one

def Nat.binaryRec'.{u} {motive : ℕ → Sort u} (zero : motive 0)
  (bit : (b : Bool) → (n : ℕ) → (n = 0 → b = true) → motive n → motive (Nat.bit b n)) (n : ℕ) :
  motive n

